class URLResolverCheckCustomErrorHandlerTests(TestCase):

    def test_check_custom_error_handlers_all_success(self):
        """
        Test that _check_custom_error_handlers returns an empty list when all
        custom error handlers are valid.
        """
        # Mock URLResolver and settings to simulate a scenario where all
        # custom error handlers are defined and valid.
        class MockURLResolver:
            def resolve_error_handler(self, status_code):
                if status_code == 400:
                    return empty_view
                elif status_code == 403:
                    return empty_view
                elif status_code == 404:
                    return empty_view
                elif status_code == 500:
                    return empty_view
                return None

        mock_resolver = MockURLResolver()
        messages = mock_resolver.check()
        self.assertEqual(len(messages), 0)

    def test_check_custom_error_handlers_invalid_handler_count(self):
        """
        Test that _check_custom_error_handlers raises an error when a custom
        error handler has an incorrect number of arguments.
        """
        class MockURLResolver:
            def resolve_error_handler(self, status_code):
                if status_code == 400:
                    return lambda request, exception, extra_arg: None  # Incorrect number of args
                elif status_code == 403:
                    return empty_view
                elif status_code == 404:
                    return empty_view
                elif status_code == 500:
                    return empty_view
                return None

        mock_resolver = MockURLResolver()
        messages = mock_resolver.check()
        self.assertEqual(len(messages), 1)
        self.assertIsInstance(messages[0], Error)
        self.assertIn("does not take the correct number of arguments", str(messages[0]))

    def test_check_custom_error_handlers_handler_not_found(self):
        """
