from sympy import Lambda, symbols
from sympy.abc import x
from sympy.core.basic import Basic
from sympy.utilities.iterables import numbered_symbols

def test_canonical_variables_empty():
    assert Basic().canonical_variables == {}

def test_canonical_variables_lambda():
    l = Lambda(x, 2 * x)
    assert l.canonical_variables == {x: symbols('_0')}

def test_canonical_variables_multiple():
    x, y = symbols('x y')
    l = Lambda(x, x + y)
    canonical = l.canonical_variables
    assert canonical == {x: symbols('_0'), y: symbols('_1')}

def test_canonical_variables_clash():
    x = symbols('x')
    _0 = symbols('_0')
    l = Lambda(x, x + 1)
    l.canonical_variables = {x: _0}
    assert l.canonical_variables == {x: symbols('_0')}

def test_canonical_variables_free_symbols():
    x, y = symbols('x y')
    l = Lambda(x, x + y)
    canonical = l.canonical_variables
    assert canonical == {x: symbols('_0'), y: symbols('_1')}

def test_canonical_variables_numbered_symbols():
    x, y, z = symbols('x y z')
    l = Lambda(x, x + y + z)
    canonical = l.canonical_variables
    assert canonical == {x: symbols('_0'), y: symbols('_1'), z: symbols('_2')}
